"use client";

import { type KeyboardEvent, useId, useState } from "react";

import { Table } from "@/components/ui/table";

import { BlockFrame } from "../parts/block-frame";
import { RoleHeader } from "./roles-permissions/role-header";
import { MatrixRowView } from "./roles-permissions/matrix-row-view";
import { nextCell, visibleRows } from "./roles-permissions/matrix-rows";
import { ReviewBar } from "./roles-permissions/review-bar";
import { useMatrix } from "./roles-permissions/use-matrix";
import { PersonAvatar } from "./shared/person-avatar";
import { ROSTER } from "./shared/roster";

/**
 * A matrix of what each role may do: roles as columns, permissions as rows in
 * groups that fold. Group checkboxes ripple across their rows, changed cells
 * show a dot, and a review bar holds the unsaved changes. Arrow keys move
 * through the grid; Home and End jump within a row, and with Ctrl, to the
 * first or last cell.
 */
export function RolesPermissions({ className }: { className?: string }) {
  const titleId = useId();
  const gridId = useId();
  const matrix = useMatrix();
  const [closed, setClosed] = useState<Set<string>>(new Set());
  const [focus, setFocus] = useState({ row: 1, column: 1 });
  const [hovered, setHovered] = useState<number | null>(null);
  const [status, setStatus] = useState("");

  const rows = visibleRows(closed);
  const columns = matrix.roles.length;
  const people = matrix.roles.reduce((total, role) => total + role.people, 0);
  const safe = { row: Math.min(focus.row, rows.length - 1), column: Math.min(focus.column, columns - 1) };
  const idFor = (row: number, column: number) => `${gridId}-r${row}-c${column}`;

  const onKeyDown = (event: KeyboardEvent<HTMLTableElement>) => {
    // Only the checkboxes move by arrow; menus and fold buttons keep their own keys.
    if (!(event.target instanceof HTMLElement) || event.target.getAttribute("role") !== "checkbox") return;
    const target = nextCell(event.key, event.ctrlKey || event.metaKey, safe.row, safe.column, rows.length, columns);
    if (!target) return;
    event.preventDefault();
    setFocus(target);
    document.getElementById(idFor(target.row, target.column))?.focus();
  };

  const fold = (group: string) =>
    setClosed((current) => {
      const next = new Set(current);
      if (next.has(group)) next.delete(group);
      else next.add(group);
      return next;
    });

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-5 py-4">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Roles and permissions
          </h2>
          <p className="text-sm text-muted-foreground">
            Harbour Street, {people} members across {columns} roles
          </p>
        </div>
        <div className="flex items-center" aria-hidden="true">
          {ROSTER.slice(0, 5).map((person) => (
            <PersonAvatar key={person.id} name={person.name} hue={person.hue} size="sm" ring className="-ml-2 first:ml-0" />
          ))}
          <span className="-ml-2 flex size-7 items-center justify-center rounded-full bg-muted text-xs font-medium ring-2 ring-card">+{people - 5}</span>
        </div>
      </header>

      <Table role="grid" aria-labelledby={titleId} onKeyDown={onKeyDown} onMouseLeave={() => setHovered(null)} className="min-w-160 border-collapse">
        <thead>
          <tr>
            <th scope="col" className="sticky left-0 z-10 bg-card px-3 py-2 text-left text-xs font-normal text-muted-foreground">
              Permission
            </th>
            {matrix.roles.map((role, column) => (
              <th key={role.id} scope="col" onMouseEnter={() => setHovered(column)} className="relative isolate px-1 py-2">
                {hovered === column ? <span aria-hidden="true" className="absolute inset-0 -z-10 rounded-t-lg bg-muted/40" /> : null}
                <RoleHeader
                  role={role}
                  onDuplicate={() => setStatus(`${matrix.duplicate(role)} added. It is not saved yet.`)}
                  onClear={() => {
                    matrix.clear(role.id);
                    setStatus(`All permissions cleared for ${role.name}.`);
                  }}
                />
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, rowIndex) => (
            <MatrixRowView
              key={row.kind === "group" ? row.group.id : row.id}
              row={row}
              rowIndex={rowIndex}
              roles={matrix.roles}
              matrix={matrix}
              open={!closed.has(row.group.id)}
              focus={safe}
              hovered={hovered}
              idFor={idFor}
              onFocusCell={(row, column) => setFocus({ row, column })}
              onHover={setHovered}
              onFold={() => fold(row.group.id)}
            />
          ))}
        </tbody>
      </Table>

      <ReviewBar
        changes={matrix.changes}
        saving={matrix.saving}
        onDiscard={() => {
          matrix.discard();
          setStatus("Changes discarded.");
        }}
        onSave={() => {
          matrix.save();
          setStatus("Permissions saved.");
        }}
      />
      <p aria-live="polite" className="sr-only">
        {status}
      </p>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { Button } from "@/components/ui/button";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";

import { ChevronDownIcon } from "../../parts/icons";
import { LockIcon } from "../icons";
import type { RoleColumn } from "./data";

/** Props for a role's column header. */
export interface RoleHeaderProps {
  role: RoleColumn;
  onDuplicate: () => void;
  onClear: () => void;
}

/** A role's name with a menu to duplicate it or clear its permissions, and how many people hold it. */
export function RoleHeader({ role, onDuplicate, onClear }: RoleHeaderProps) {
  return (
    <div className="flex flex-col items-center gap-0.5">
      {role.locked ? (
        <span className="flex h-8 items-center gap-1 px-2 text-sm font-medium">
          <LockIcon aria-hidden="true" className="size-3.5 text-muted-foreground" />
          {role.name}
        </span>
      ) : (
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="ghost" size="sm" aria-label={`${role.name} role options`}>
              <span className="max-w-24 truncate">{role.name}</span>
              <ChevronDownIcon aria-hidden="true" className="size-3.5" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="center">
            <DropdownMenuItem onSelect={onDuplicate}>Duplicate role</DropdownMenuItem>
            <DropdownMenuItem onSelect={onClear}>Clear all permissions</DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      )}
      <span className="text-xs font-normal text-muted-foreground">
        {role.people === 0 ? "Nobody yet" : `${role.people} ${role.people === 1 ? "person" : "people"}`}
      </span>
    </div>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

