/** A role as a column of the matrix. */
export interface RoleColumn {
  id: string;
  name: string;
  people: number;
  /** The owner's column cannot change. */
  locked?: boolean;
  hue: number;
}

/** A group of permissions that folds open and shut. */
export interface PermissionGroup {
  id: string;
  name: string;
  permissions: { id: string; name: string }[];
}

/** The roles at Harbour Street, owner first. */
export const START_ROLES: RoleColumn[] = [
  { id: "owner", name: "Owner", people: 1, locked: true, hue: 1 },
  { id: "admin", name: "Admin", people: 2, hue: 2 },
  { id: "practitioner", name: "Practitioner", people: 6, hue: 3 },
  { id: "desk", name: "Front desk", people: 3, hue: 4 },
  { id: "billing", name: "Billing", people: 1, hue: 5 },
];

/** The permissions, in four groups. */
export const GROUPS: PermissionGroup[] = [
  {
    id: "bookings",
    name: "Bookings",
    permissions: [
      { id: "schedule.view", name: "View the schedule" },
      { id: "bookings.create", name: "Create bookings" },
