      { id: "plan.manage", name: "Manage the plan" },
    ],
  },
];

/** Every permission id, in matrix order. */
export const ALL_PERMISSIONS = GROUPS.flatMap((group) => group.permissions.map((permission) => permission.id));

const GRANTS = {
  owner: ALL_PERMISSIONS,
  admin: ALL_PERMISSIONS.filter((id) => id !== "plan.manage" && id !== "refunds.issue"),
  practitioner: ["schedule.view", "bookings.create", "bookings.move", "records.view", "notes.edit"],
  desk: ["schedule.view", "bookings.create", "bookings.move", "records.view", "team.invite"],
  billing: ["schedule.view", "invoices.view", "refunds.issue", "plan.manage"],
} satisfies Record<string, string[]>;

/** The key of one cell. */
export const cellKey = (role: string, permission: string) => `${role}:${permission}`;

/** The saved grants when the block opens, as a set of cell keys. */
export const START_GRANTS = new Set(Object.entries(GRANTS).flatMap(([role, ids]) => ids.map((id) => cellKey(role, id))));

"use client";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { ChevronDownIcon } from "../../parts/icons";
import { cellKey, type RoleColumn } from "./data";
import { CheckCell } from "./check-cell";
import type { MatrixRow } from "./matrix-rows";
import type { Matrix } from "./use-matrix";

/** Props for one row of the matrix. */
export interface MatrixRowViewProps {
  row: MatrixRow;
  rowIndex: number;
  roles: RoleColumn[];
  matrix: Matrix;
  open: boolean;
  focus: { row: number; column: number };
  hovered: number | null;
  idFor: (row: number, column: number) => string;
  onFocusCell: (row: number, column: number) => void;
  onHover: (column: number) => void;
  onFold: () => void;
}

/** A group header row with a fold button and mixed checkboxes, or a permission row with one checkbox per role. */
export function MatrixRowView({ row, rowIndex, roles, matrix, open, focus, hovered, idFor, onFocusCell, onHover, onFold }: MatrixRowViewProps) {
  const isGroup = row.kind === "group";
  const ids = row.group.permissions.map((permission) => permission.id);

  return (
    <tr className="border-t border-border">
      <th scope="row" className="sticky left-0 z-10 bg-card py-1 pr-3 pl-3 text-left font-normal">
        {isGroup ? (
          <Button variant="ghost" size="sm" className="-ml-2" aria-expanded={open} onClick={onFold}>
            <ChevronDownIcon aria-hidden="true" className={cn("size-3.5 motion-safe:transition-transform", !open && "-rotate-90")} />
            {row.group.name}
            <span className="font-normal text-muted-foreground">{ids.length}</span>
          </Button>
        ) : (
          <span className="block pl-7 text-sm">{row.name}</span>
        )}
      </th>
      {roles.map((role, column) => {
        const keys = isGroup ? ids.map((id) => cellKey(role.id, id)) : [cellKey(role.id, row.id)];
        const count = keys.filter((key) => matrix.draft.has(key)).length;
        const checked = role.locked || count === keys.length ? true : count === 0 ? false : "mixed";
        const label = isGroup ? `${row.group.name}, all ${ids.length} permissions, ${role.name}` : `${row.name}, ${role.name}`;
        return (
          <td key={role.id} role="gridcell" onMouseEnter={() => onHover(column)} className="relative isolate px-1 py-1 text-center">
            {hovered === column ? <span aria-hidden="true" className="absolute inset-0 -z-10 bg-muted/40" /> : null}
            <CheckCell
              cellId={idFor(rowIndex, column)}
              checked={checked}
              locked={role.locked}
              dirty={!isGroup && matrix.isDirty(keys[0]!)}
              label={label}
              tabbable={focus.row === rowIndex && focus.column === column}
              onFocus={() => onFocusCell(rowIndex, column)}
              onToggle={() => (isGroup ? matrix.toggleGroup(role.id, ids) : matrix.toggle(role.id, row.id))}
            />
          </td>
        );
      })}
    </tr>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

/** Props for one checkbox in the matrix. */
export interface CheckCellProps {
  checked: boolean | "mixed";
  locked?: boolean;
  dirty?: boolean;
  label: string;
  /** Whether this cell holds the grid's single tab stop. */
  tabbable: boolean;
  cellId: string;
  onToggle: () => void;
  onFocus: () => void;
}

/**
 * A checkbox cell. Locked cells read as checked and do nothing. A changed,
 * unsaved cell shows a dot that pops in.
 */
export function CheckCell({ checked, locked, dirty, label, tabbable, cellId, onToggle, onFocus }: CheckCellProps) {
  const reduce = useReducedMotion();
  const on = checked === true;

  return (
    <Button
      type="button"
      variant="ghost"
      size="icon"
      role="checkbox"
      id={cellId}
      aria-checked={checked}
      aria-disabled={locked || undefined}
      aria-label={label}
      tabIndex={tabbable ? 0 : -1}
      onFocus={onFocus}
      onClick={() => !locked && onToggle()}
      className="relative size-8"
    >
      <span
        aria-hidden="true"
        className={cn(
          "flex size-4 items-center justify-center rounded-sm border motion-safe:transition-colors",
          locked ? "border-border bg-muted text-muted-foreground" : checked ? "border-primary bg-primary text-primary-foreground" : "border-muted-foreground/60",
        )}
      >
        {checked === "mixed" ? (
          <span className="h-0.5 w-2 rounded-full bg-current" />
        ) : on ? (
          <svg viewBox="0 0 16 16" className="size-3">
            <motion.path
              d="M3.5 8.5l3 3 6-7"
              fill="none"
              stroke="currentColor"
              strokeWidth="2.2"
              strokeLinecap="round"
              strokeLinejoin="round"
              initial={{ pathLength: reduce || locked ? 1 : 0 }}
              animate={{ pathLength: 1 }}
              transition={{ duration: 0.18 }}
            />
          </svg>
        ) : null}
      </span>
      <AnimatePresence>
        {dirty ? (
          <motion.span
            aria-hidden="true"
            initial={{ scale: reduce ? 1 : 0 }}
            animate={{ scale: 1 }}
            exit={{ scale: reduce ? 1 : 0, opacity: 0 }}
            transition={{ type: "spring", stiffness: 600, damping: 20 }}
            className="absolute top-1 right-1 size-1.5 rounded-full bg-chart-3"
          />
        ) : null}
      </AnimatePresence>
    </Button>
  );
}

import { GROUPS, type PermissionGroup } from "./data";

/** One visible row of the matrix: a group header, or a permission inside an open group. */
export type MatrixRow =
  | { kind: "group"; group: PermissionGroup }
  | { kind: "permission"; group: PermissionGroup; id: string; name: string };

/** The rows that show, given which groups are folded shut. */
export function visibleRows(closed: Set<string>): MatrixRow[] {
  return GROUPS.flatMap((group): MatrixRow[] => [
    { kind: "group", group },
    ...(closed.has(group.id) ? [] : group.permissions.map((permission) => ({ kind: "permission" as const, group, ...permission }))),
  ]);
}

/**
 * Where focus lands after a key press in a grid of `rows` by `columns`, or
 * null for a key the grid does not handle.
 */
export function nextCell(key: string, ctrl: boolean, row: number, column: number, rows: number, columns: number) {
  const lastRow = rows - 1;
  const lastColumn = columns - 1;
  switch (key) {
    case "ArrowUp":
      return { row: Math.max(0, row - 1), column };
    case "ArrowDown":
      return { row: Math.min(lastRow, row + 1), column };
    case "ArrowLeft":
      return { row, column: Math.max(0, column - 1) };
    case "ArrowRight":
      return { row, column: Math.min(lastColumn, column + 1) };
    case "Home":
      return ctrl ? { row: 0, column: 0 } : { row, column: 0 };
    case "End":
      return ctrl ? { row: lastRow, column: lastColumn } : { row, column: lastColumn };
    default:
      return null;
  }
}

"use client";

import { useReducedMotion } from "motion/react";
import { useState } from "react";

import { useTimers } from "../../auth/shared/use-timers";
import { ALL_PERMISSIONS, cellKey, type RoleColumn, START_GRANTS, START_ROLES } from "./data";

/**
 * Holds the roles, the saved grants and the draft the person is editing.
 * A group toggle ripples across its permissions one after another.
 */
export function useMatrix() {
  const reduce = useReducedMotion();
  const { later } = useTimers();
  const [roles, setRoles] = useState<RoleColumn[]>(START_ROLES);
  const [savedRoles, setSavedRoles] = useState<RoleColumn[]>(START_ROLES);
  const [saved, setSaved] = useState<Set<string>>(START_GRANTS);
  const [draft, setDraft] = useState<Set<string>>(START_GRANTS);
  const [saving, setSaving] = useState(false);

  const set = (key: string, on: boolean) =>
    setDraft((current) => {
      if (current.has(key) === on) return current;
      const next = new Set(current);
      if (on) next.add(key);
      else next.delete(key);
      return next;
    });

  const toggle = (role: string, permission: string) => {
    const key = cellKey(role, permission);
    set(key, !draft.has(key));
  };

  const toggleGroup = (role: string, permissions: string[]) => {
    const on = !permissions.every((id) => draft.has(cellKey(role, id)));
    permissions.forEach((id, index) => {
      if (reduce || index === 0) set(cellKey(role, id), on);
      else later(() => set(cellKey(role, id), on), index * 45);
    });
  };

  const duplicate = (role: RoleColumn) => {
    const copies = roles.filter((item) => item.name.startsWith(`${role.name} copy`)).length;
    const id = `${role.id}-copy-${Date.now()}`;
    const name = copies ? `${role.name} copy ${copies + 1}` : `${role.name} copy`;
    setRoles((current) => {
      const at = current.findIndex((item) => item.id === role.id);
      return [...current.slice(0, at + 1), { id, name, people: 0, hue: ((role.hue + 1) % 5) + 1 }, ...current.slice(at + 1)];
    });
    setDraft((current) => {
      const next = new Set(current);
      for (const permission of ALL_PERMISSIONS) if (current.has(cellKey(role.id, permission))) next.add(cellKey(id, permission));
      return next;
    });
    return name;
  };

  const dirtyCells = [...new Set([...draft, ...saved])].filter((key) => draft.has(key) !== saved.has(key));
  const newRoles = roles.filter((role) => !savedRoles.some((item) => item.id === role.id));
  const changes = dirtyCells.filter((key) => !newRoles.some((role) => key.startsWith(`${role.id}:`))).length + newRoles.length;

  return {
    roles,
    draft,
    saving,
    changes,
    isDirty: (key: string) => draft.has(key) !== saved.has(key),
    toggle,
    toggleGroup,
    duplicate,
    clear: (role: string) =>
      setDraft((current) => new Set([...current].filter((key) => !key.startsWith(`${role}:`)))),
    discard: () => {
      setDraft(saved);
      setRoles(savedRoles);
    },
    save: () => {
      setSaving(true);
      later(() => {
        setSaved(draft);
        setSavedRoles(roles);
        setSaving(false);
      }, 700);
    },
  };
}

/** The state and actions `useMatrix` returns. */
export type Matrix = ReturnType<typeof useMatrix>;

