/** Props for the review bar. It shows while `changes` is above zero. */
export interface ReviewBarProps {
  changes: number;
  saving: boolean;
  onDiscard: () => void;
  onSave: () => void;
}

/** A bar that slides up while there are unsaved changes, with Discard and Save. */
export function ReviewBar({ changes, saving, onDiscard, onSave }: ReviewBarProps) {
  const reduce = useReducedMotion();
  return (
    <AnimatePresence>
      {changes > 0 ? (
        <motion.div
          initial={{ y: reduce ? 0 : "100%", opacity: reduce ? 0 : 1 }}
          animate={{ y: 0, opacity: 1 }}
          exit={{ y: reduce ? 0 : "100%", opacity: reduce ? 0 : 1 }}
          transition={{ type: "spring", stiffness: 420, damping: 38 }}
          className="sticky bottom-0 z-10 flex flex-wrap items-center justify-between gap-3 border-t border-border bg-card px-5 py-3"
        >
          <p className="flex items-center gap-2 text-sm">
            <span aria-hidden="true" className="size-2 rounded-full bg-chart-3" />
            <span>
              <RollingText text={String(changes)} className="font-semibold" /> unsaved {changes === 1 ? "change" : "changes"}
            </span>
          </p>
          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" disabled={saving} onClick={onDiscard}>
              Discard
            </Button>
            <Button size="sm" disabled={saving} aria-busy={saving} onClick={onSave}>
              <span aria-hidden="true" className="flex size-4 items-center justify-center">
                {saving ? <LoaderIcon className="size-4 motion-safe:animate-spin" /> : null}
              </span>
              Save changes
            </Button>
          </div>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}

