/** A person's initials, at most two letters. */
export const initials = (name: string) =>
  name
    .split(/\s+/)
    .map((part) => part[0] ?? "")
    .join("")
    .slice(0, 2)
    .toUpperCase();

/** Guesses a display name from an email address, such as "dana.reyes@..." to "Dana Reyes". */
export const nameFromEmail = (email: string) =>
  (email.split("@")[0] ?? email)
    .split(/[._-]+/)
    .filter(Boolean)
    .map((part) => part[0]!.toUpperCase() + part.slice(1))
    .join(" ");
